        candidates = sorted(candidates)
        best = []
        for step in range(1, max(h, w) + 1):
            groups = {}
            for x in candidates:
                groups.setdefault(x % step, []).append(x)
            for seq in groups.values():
                if len(seq) > len(best):
                    best = seq
        return best

